scripts.script:
// 1. 定义受影响的六大属性
const validStats = ["liliang", "shenfa", "tipo", "neixi", "qigan", "shencai"];

// 2. 给属性本身加优势
for (const s of validStats) {
    const flag = s + "CheckLevel";
    actor.xjzlStatuses[flag] = (actor.xjzlStatuses[flag] || 0) + 1;
}

// 3. 给对应的技能加优势 (排除悟性系技能)
// 悟性系技能列表 (硬编码排除，比判断属性归属更直接)
const wuxingSkills = ["wuxue", "jianding", "bagua", "shili"];

for (const sk of Object.keys(CONFIG.XJZL.skills)) {
    if (!wuxingSkills.includes(sk)) {
        const flag = sk + "CheckLevel";
        actor.xjzlStatuses[flag] = (actor.xjzlStatuses[flag] || 0) + 1;
    }
}

if (args.move.type === 'feint') {
    args.output.damage += 15;
    args.output.bonusDesc.push("仁经要略: +15");
}

if (args.move.type === 'feint') {
    args.output.damage += 20;
    args.output.bonusDesc.push("仁经要略: +20");
}

const t = args.target;
const isEvil = (t.system.social?.exing >= 100 && t.system.social?.xiayi <= 50) || t.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'shengde_evil_mark');
if (isEvil) {
    args.config.amount += 10;
    ui.notifications.info('圣德天书：感应到恶念，伤害+10');
}

const t = args.target;
const isEvil = (t.system.social?.exing >= 100 && t.system.social?.xiayi <= 50) || t.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'shengde_evil_mark');
if (isEvil) {
    args.config.amount += 20;
    ui.notifications.info('圣德天书：感应到恶念，伤害+20');
}

const t = args.target;
const isEvil = (t.system.social?.exing >= 100 && t.system.social?.xiayi <= 50) || t.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'shengde_evil_mark');
if (isEvil) {
    args.config.amount += 30;
    ui.notifications.info('圣德天书：感应到恶念，伤害+30');
}

// 计算当前定力豁免 DC: 15 + 神采等级 (总值/10 向下取整)
const shencaiLvl = Math.floor(S.stats.shencai.total / 10);
const dc = 15 + shencaiLvl;

const cardContent = `
<div class="xjzl-chat-card">
    <div style="padding: 5px; padding-left: 10px; border-left: 4px solid #d35400; background: rgba(211, 84, 0, 0.05); margin-left: 2px;">
        <div style="font-weight: bold; color: #b33900; font-size: 1.1em;">
            <i class="fas fa-sun"></i> 正气浩荡
        </div>
        <div style="font-size: 0.9em; margin-top: 5px; color: #555;">
            请要求视野范围内，尚未暴漏恶念的敌人进行一次 <b>[定力]</b> 检定。<br>
            检定难度 (DC)：<span style="font-weight: bold; color: #d35400;">${dc}</span><br>
            <span style="color: #888;">* 若目标失败，请手动为其添加【恶念显露】状态。</span>
        </div>
    </div>
</div>`;

ChatMessage.create({
    content: cardContent,
    speaker: ChatMessage.getSpeaker({ actor: actor })
});

S.combat.damages.weapon.mod += 10;
S.arts.duanzao.checkMod += 1;
S.arts.chengyi.checkMod += 1;
S.arts.zhibao.checkMod += 1;

if (game.combat) {
    const turns = game.combat.turns;
    const myIdx = turns.findIndex(c => c.actorId === actor.id);
    const tIdx = turns.findIndex(c => c.actorId === args.target.id);
    if (myIdx !== -1 && tIdx !== -1) {
        if (tIdx < myIdx) args.config.amount += 10; // Target higher order
        else if (tIdx > myIdx) args.config.amount -= 10;
    }
}

if (game.combat) {
    const turns = game.combat.turns;
    const myIdx = turns.findIndex(c => c.actorId === actor.id);
    const tIdx = turns.findIndex(c => c.actorId === args.target.id);
    if (myIdx !== -1 && tIdx !== -1) {
        if (tIdx < myIdx) args.config.amount += 15;
        else if (tIdx > myIdx) args.config.amount -= 5;
    }
}

if (game.combat) {
    const turns = game.combat.turns;
    const myIdx = turns.findIndex(c => c.actorId === actor.id);
    const tIdx = turns.findIndex(c => c.actorId === args.target.id);
    if (myIdx !== -1 && tIdx !== -1) {
        if (tIdx < myIdx) args.config.amount += 20;
    }
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const effectData = {
    name: "鬼谷压制",
    icon: "icons/svg/downgrade.svg",
    description: "闪避下降 (鬼谷玄功)",
    flags: { "xjzl-system": { slug: "guigu_dodge_debuff", stackable: true } },
    changes: [{ key: "system.combat.dodge", mode: 2, value: -1 }]
};
await game.xjzl.api.effects.addEffect(args.target, effectData);

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const effectData = {
    name: "鬼谷压制II",
    icon: "icons/svg/downgrade.svg",
    description: "闪避下降 (鬼谷玄功)",
    flags: { "xjzl-system": { slug: "guigu_dodge_debuff_2", stackable: true } },
    changes: [{ key: "system.combat.dodge", mode: 2, value: -2 }]
};
await game.xjzl.api.effects.addEffect(args.target, effectData);

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const effectData = {
    name: "鬼谷压制III",
    icon: "icons/svg/downgrade.svg",
    description: "闪避下降 (鬼谷玄功)",
    flags: { "xjzl-system": { slug: "guigu_dodge_debuff_3", stackable: true } },
    changes: [{ key: "system.combat.dodge", mode: 2, value: -3 }]
};
await game.xjzl.api.effects.addEffect(args.target, effectData);

if (!args.isHit) return;
// 检查目标是否开启了架招
if (args.target.system.martial?.stanceActive) return;

// 投掷 1d4
const roll = await new Roll("1d4").evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);
const result = roll.total;

let effectName = "";
let effectId = "";
let desc = "";

if (result === 1) {
    effectName = "击飞 3 米";
    desc = "强劲的力道将目标击飞！<br><span style='color:#e67e22;'>*(请 GM 手动移动 Token)*</span>";
} else if (result === 2) {
    effectName = "倒地";
    effectId = "prone";
    desc = "目标失去平衡，重重摔倒在地。";
} else if (result === 3) {
    effectName = "错骨";
    effectId = "cuogu";
    desc = "目标骨骼错位，攻防受损 (持续 1 回合)。";
} else if (result === 4) {
    effectName = "缚身";
    effectId = "fushen";
    desc = "目标身形受制，步履维艰 (持续 1 回合)。";
}

// 构造并发送战报卡片
const content = `
<div class="xjzl-chat-card item-card">
    <div class="card-content-wrapper">
        <div style="font-weight:bold; color:#2c3e50; border-bottom: 2px solid #ccc; padding-bottom: 3px; margin-bottom: 5px;">
            <i class="fas fa-dice"></i> 鬼谷玄功·千变万化
        </div>
        <div style="font-size:0.9em; margin-bottom: 8px;">
            目标: <b>${args.target.name}</b> (无架招)
        </div>
        <div style="text-align:center; font-size:1.2em; font-weight:bold; background:rgba(0,0,0,0.05); border:1px solid #ccc; border-radius:4px; padding:4px; margin-bottom: 8px;">
            1d4 ➔ <span style="color:#c0392b;">${result}</span>
        </div>
        <div style="font-size:0.9em; color:#444;">
            触发效果: <b style="color:#27ae60;">${effectName}</b><br>
            <span style="color:#666; font-style: italic;">${desc}</span>
        </div>
    </div>
</div>`;

ChatMessage.create({
    user: game.user.id,
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: content
});

// 自动施加状态
if (effectId) {
    const statusConfig = CONFIG.statusEffects.find(e => e.id === effectId);
    if (statusConfig) {
        const eData = foundry.utils.deepClone(statusConfig);
        eData.origin = thisItem.uuid;
        // 如果是错骨或缚身，强行设置持续回合为 1
        if (result === 3 || result === 4) {
            eData.duration = { rounds: 1 };
        }
        await game.xjzl.api.effects.addEffect(args.target, eData);
    }
}

if (args.target.system.social?.exing > 0) {
    args.flags.grantHit += 5;
}

if (args.target.system.resources?.shanie > 0) {
    args.config.amount += 10;
}

if (args.target.system.social?.exing > 0) {
    args.flags.grantHit += 10;
}

if (args.target.system.resources?.shanie > 0) {
    args.config.amount += 15;
}

if (!game.combat) return;
const myDisp = actor.token?.disposition ?? actor.prototypeToken?.disposition ?? 1;
const enemies = game.combat.combatants.filter(c => c.actor && c.token.disposition !== myDisp && c.token.disposition !== 0).map(c => c.actor);

const sourceEffect = thisItem.effects.getName("刑（领悟）");
if (sourceEffect) {
    const eff = sourceEffect.toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    for (const enemy of enemies) {
        await game.xjzl.api.effects.addEffect(enemy, eff);
    }
    actor.showFloatyText("法禁·立威！", { fill: "#ff0000" });
}

if (!game.combat) return;
const myDisp = actor.token?.disposition ?? actor.prototypeToken?.disposition ?? 1;
const enemies = game.combat.combatants.filter(c => c.actor && c.token.disposition !== myDisp && c.token.disposition !== 0).map(c => c.actor);

const sourceEffect = thisItem.effects.getName("刑");
if (sourceEffect) {
    const eff = sourceEffect.toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    for (const enemy of enemies) {
        await game.xjzl.api.effects.addEffect(enemy, eff);
    }
    actor.showFloatyText("法禁·制民！", { fill: "#ff0000" });
}

if (!game.combat) return;
const myDisp = actor.token?.disposition ?? actor.prototypeToken?.disposition ?? 1;
const enemies = game.combat.combatants.filter(c => c.actor && c.token.disposition !== myDisp && c.token.disposition !== 0).map(c => c.actor);
const allies = game.combat.combatants.filter(c => c.actor && c.token.disposition === myDisp).map(c => c.actor);

const sourceXing = thisItem.effects.getName("刑");
if (sourceXing) {
    const effXing = sourceXing.toObject();
    delete effXing._id;
    effXing.origin = thisItem.uuid;
    for (const enemy of enemies) await game.xjzl.api.effects.addEffect(enemy, effXing);
}

const sourceShang = thisItem.effects.getName("赏");
if (sourceShang) {
    const effShang = sourceShang.toObject();
    delete effShang._id;
    effShang.origin = thisItem.uuid;
    for (const ally of allies) await game.xjzl.api.effects.addEffect(ally, effShang);
}

actor.showFloatyText("法禁·赏罚分明！", { fill: "#f1c40f" });
